python3 -c 'import json, numpy as np, math; from scipy.stats import t; root="kran-research/projects/max-pool-8b/data"; rows=json.load(open(root+"/ref/split.json")); y=np.array([r["pos"] for r in rows]); sp=np.array([r["split"] for r in rows]); rf=np.where((sp=="refit")&(y==0))[0]; ep=np.where((sp=="eval")&(y==1))[0]; en=np.where((sp=="eval")&(y==0))[0]; thr=lambda x: float(np.sort(np.asarray(x))[::-1][max(1,int(math.floor(.01*(len(x)+1))))-1]); catch=lambda arr: ((arr[ep]>thr(arr[rf])).mean(), (arr[en]>thr(arr[rf])).mean()); states=["main__seed0__step150","main__seed1__step150","main__seed2__step150"]; vals=[]; print("refit_true",len(rf),"eval_false",len(ep),"eval_true",len(en)); c=np.load(root+"/states/clean/scores.npz"); print("clean max", catch(c["max"])[0]*100); import pathlib; [ (lambda z,s: (vals.append(catch(z["max"])[0]), print(s, "max", catch(z["max"])[0]*100, "fpr", catch(z["max"])[1]*100, "avg", catch(z["mean"])[0]*100, "last", catch(z["last"])[0]*100)))(np.load(root+"/states/"+s+"/scores.npz"),s) for s in states ]; v=np.array(vals); h=t.ppf(.975,len(v)-1)*v.std(ddof=1)/np.sqrt(len(v)); print("mean",v.mean()*100,"seed_ci",(v.mean()-h)*100,(v.mean()+h)*100); [print(s, "random max", catch(np.load(root+"/states/"+s+"/scores.npz")["max"])[0]*100) for s in ["random__seed0__step150","random__seed1__step150"]]'
